args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?director ?directorLabel ?deathPlace ?deathPlaceLabel WHERE {
  dbr:The_Alster_Case dbo:director ?director .
  OPTIONAL { ?director dbo:deathPlace ?deathPlace . }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), "EN")) }
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER(langMatches(lang(?deathPlaceLabel), "EN")) }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>

SELECT DISTINCT ?director ?deathPlace WHERE {
  dbr:The_Alster_Case dbo:director ?director .
  OPTIONAL { ?director dbo:deathPlace ?deathPlace . }
}

